const $=id=>document.getElementById(id);
const defaults={courses:['Computer Science','Mathematics','English'],events:[['2026-10-02','Reading response',2],['2026-10-05','Problem set 03',1],['2026-10-07','Lab 04: Data structures',0],['2026-10-09','Essay outline',2],['2026-10-12','Problem set 04',1],['2026-10-14','Project proposal',0],['2026-10-16','Reading response',2],['2026-10-19','Problem set 05',1],['2026-10-21','Project 01 due',0],['2026-10-22','Midterm exam',1],['2026-10-23','Essay 01 due',2],['2026-10-26','Lab 06: Recursion',0],['2026-10-28','Problem set 06',1],['2026-10-30','Reading response',2],['2026-11-04','Research paper',2]].map((e,i)=>({date:e[0],title:e[1],course:e[2],done:i===0||i===1,id:i+1}))};
let state;try{state=JSON.parse(localStorage.getItem('syllabus-calendar'))||defaults}catch{state=defaults}let shown=new Date(2026,9,1),view='month';const reference=new Date(2026,9,16);const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const dateOf=s=>new Date(s+'T12:00:00');
function save(){localStorage.setItem('syllabus-calendar',JSON.stringify(state))}function toast(t){$('toast').textContent=t;$('toast').classList.add('visible');setTimeout(()=>$('toast').classList.remove('visible'),3500)}
state.syllabi ??= state.courses.slice(3).map((name,i)=>({id:'legacy-'+i,name,uploadedAt:null}));
function render(){const rows=$('syllabiRows');rows.replaceChildren();const records=[...state.syllabi].sort((a,b)=>(b.uploadedAt||'').localeCompare(a.uploadedAt||''));for(const record of records){const row=document.createElement('tr'),name=document.createElement('td'),date=document.createElement('td');name.textContent=record.name;if(record.uploadedAt){const time=document.createElement('time');time.dateTime=record.uploadedAt;time.textContent=new Date(record.uploadedAt).toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'});time.title=new Date(record.uploadedAt).toLocaleString();date.append(time)}else{date.textContent='Not recorded'}row.append(name,date);rows.append(row)}$('syllabiEmpty').hidden=records.length>0;document.querySelector('.syllabi-table table').hidden=records.length===0}
function showPage(){const page=location.hash==='#my-syllabi'?'syllabi':location.hash==='#calendar-sync'?'sync':'upload';$('syllabiPage').hidden=page!=='syllabi';$('syncPage').hidden=page!=='sync';document.querySelector('.upload-banner').hidden=page!=='upload';for(const [id,key] of [['calendarNav','upload'],['syllabiNav','syllabi'],['syncNav','sync']]){const active=page===key;$(id).classList.toggle('active',active);if(active)$(id).setAttribute('aria-current','page');else $(id).removeAttribute('aria-current')}document.querySelector('.breadcrumb strong').textContent=page==='syllabi'?'My syllabi':page==='sync'?'Calendar sync':'upload syllabus';render()}
window.addEventListener('hashchange',showPage);
function openUpload(){ $('formError').textContent='';$('uploadDialog').showModal() }$('uploadBanner').onclick=openUpload;$('syllabiNav').onclick=()=>{location.hash='my-syllabi';showPage()};$('calendarNav').onclick=()=>{location.hash='upload-syllabus';showPage()};$('closeDialog').onclick=()=>$('uploadDialog').close();$('uploadDialog').onclick=e=>{if(e.target===$('uploadDialog'))$('uploadDialog').close()};$('help').onclick=()=>toast('Upload a TXT syllabus or paste its text to extract dates.');
const fileButton=document.createElement('button');fileButton.type='button';fileButton.className='button white';fileButton.textContent='Choose a TXT file';fileButton.onclick=()=>$('fileInput').click();$('syllabusForm').insertBefore(fileButton,$('syllabusForm').querySelector('label'));$('fileInput').onchange=async()=>{const f=$('fileInput').files[0];if(!f)return;if(f.size>10485760){toast('Please use a text file under 10 MB.');return}$('syllabusText').value=await f.text();if(!$('courseName').value)$('courseName').value=f.name.replace(/\.txt$/i,'');$('fileInput').value=''};
$('uploadBanner').ondragover=e=>{e.preventDefault()};document.querySelector('.upload-banner').ondragover=e=>e.preventDefault();document.querySelector('.upload-banner').ondrop=async e=>{e.preventDefault();const file=e.dataTransfer.files[0];if(!file)return;if(!file.name.endsWith('.txt')||file.size>10485760){toast('Please use a text file under 10 MB.');return}openUpload();$('courseName').value=file.name.replace(/\.txt$/i,'');$('syllabusText').value=await file.text()};
const monthNames='January February March April May June July August September October November December'.split(' ');
function parseSyllabus(text){const matches=[];for(const line of text.split(/\r?\n/)){const pattern=/(\d{4}-\d{1,2}-\d{1,2})|((?:Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:tember)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)\.?\s+\d{1,2}(?:st|nd|rd|th)?(?:,?\s+\d{4})?)|(\d{1,2}\/\d{1,2}(?:\/\d{2,4})?)/i;const m=line.match(pattern);if(!m)continue;let y=2026,mo,day;const raw=m[0];if(m[1]){[y,mo,day]=raw.split('-').map(Number);mo--}else if(m[2]){const parts=raw.match(/([a-z]+)\.?\s+(\d+)(?:st|nd|rd|th)?(?:,?\s+(\d{4}))?/i);mo=monthNames.findIndex(n=>n.toLowerCase().startsWith(parts[1].toLowerCase()));day=+parts[2];if(parts[3])y=+parts[3]}else{const parts=raw.split('/').map(Number);mo=parts[0]-1;day=parts[1];if(parts[2])y=parts[2]<100?2000+parts[2]:parts[2]}const d=new Date(y,mo,day);if(d.getFullYear()!==y||d.getMonth()!==mo||d.getDate()!==day)continue;let title=line.replace(raw,'').replace(/^[\s:—–\-•]+|[\s:—–\-]+$/g,'');if(!title)title='Course deadline';matches.push({date:iso(d),title})}return matches}
$('syllabusForm').onsubmit=e=>{e.preventDefault();const events=parseSyllabus($('syllabusText').value);if(!events.length){$('formError').textContent='No dates found. Try “October 22, 2026 — Midterm exam” or “10/22 — Midterm exam”.';return}state.syllabi.push({id:Date.now(),name:$('courseName').value.trim(),uploadedAt:new Date().toISOString(),text:$('syllabusText').value});const course=state.courses.length;state.courses.push($('courseName').value.trim());events.forEach((e,i)=>state.events.push({...e,course,done:false,id:Date.now()+i}));shown=new Date(dateOf(events[0].date).getFullYear(),dateOf(events[0].date).getMonth(),1);save();render();$('uploadDialog').close();$('syllabusForm').reset();toast(`${events.length} dates added to your calendar. Your syllabus has been saved.`)};
function exportCalendar(){const esc=s=>s.replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');let lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Syllabus-to-Calendar//EN','CALSCALE:GREGORIAN'];state.events.filter(e=>!e.done&&e.course>=3).forEach(e=>{const end=dateOf(e.date);end.setDate(end.getDate()+1);lines.push('BEGIN:VEVENT',`UID:${e.id}@syllabus-to-calendar`,`DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').split('.')[0]}Z`,`DTSTART;VALUE=DATE:${e.date.replace(/-/g,'')}`,`DTEND;VALUE=DATE:${iso(end).replace(/-/g,'')}`,`SUMMARY:${esc(e.title)}`,`DESCRIPTION:${esc(state.courses[e.course])}`,'END:VEVENT')});lines.push('END:VCALENDAR');const url=URL.createObjectURL(new Blob([lines.join('\r\n')+'\r\n'],{type:'text/calendar'}));const a=document.createElement('a');a.href=url;a.download='syllabus-calendar.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Calendar exported. Import it into Google, Apple, or Outlook Calendar.')};render();

const sidebarToggle=$('sidebarToggle');function setSidebarCollapsed(collapsed){document.body.classList.toggle('sidebar-collapsed',collapsed);sidebarToggle.setAttribute('aria-expanded',String(!collapsed));sidebarToggle.setAttribute('aria-label',collapsed?'Expand sidebar':'Collapse sidebar');sidebarToggle.title=collapsed?'Expand sidebar':'Collapse sidebar';sidebarToggle.textContent=collapsed?'☰':'◧';$('sidebar').inert=collapsed;try{localStorage.setItem('syllabus-sidebar-collapsed',String(collapsed))}catch{}}sidebarToggle.onclick=()=>setSidebarCollapsed(!document.body.classList.contains('sidebar-collapsed'));try{setSidebarCollapsed(localStorage.getItem('syllabus-sidebar-collapsed')==='true')}catch{}

const cursorLightingQuery=matchMedia('(hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference)');const cursorLight=document.createElement('div');cursorLight.className='cursor-light';cursorLight.setAttribute('aria-hidden','true');document.body.append(cursorLight);let cursorFrame=0,cursorX=0,cursorY=0;document.addEventListener('pointermove',event=>{if(!cursorLightingQuery.matches||event.pointerType==='touch')return;cursorX=event.clientX;cursorY=event.clientY;if(!cursorFrame)cursorFrame=requestAnimationFrame(()=>{cursorLight.style.setProperty('--cursor-x',cursorX+'px');cursorLight.style.setProperty('--cursor-y',cursorY+'px');cursorLight.classList.add('visible');cursorFrame=0})},{passive:true});document.documentElement.addEventListener('pointerleave',()=>cursorLight.classList.remove('visible'));window.addEventListener('blur',()=>cursorLight.classList.remove('visible'));cursorLightingQuery.addEventListener('change',()=>cursorLight.classList.remove('visible'));

showPage();

$('syncNav').onclick=()=>{location.hash='calendar-sync';showPage()};for(const id of ['googleExport','appleExport'])$(id).onclick=()=>{if(!state.syllabi.length){toast('Upload a syllabus first to export your dates.');return}exportCalendar()};
